import numpy as np, time
from scipy.spatial.transform import Rotation
from scipy.ndimage import binary_dilation
from scipy.signal import fftconvolve
from PIL import Image, ImageDraw, ImageFont
font=ImageFont.truetype('/opt/conda/fonts/DejaVuSans.ttf',80)
# load all atom and ca
pts_all=[]; ca=[]; chains=[]
with open('inputs/protein.shape.q1.pdb') as f:
 for line in f:
  if line.startswith('ATOM'):
   c=line[21]; xyz=np.array([float(line[30:38]),float(line[38:46]),float(line[46:54])]); pts_all.append(xyz)
   if line[12:16].strip()=='CA': chains.append((c,xyz))
from collections import defaultdict
seqs=defaultdict(list)
for c,xyz in chains: seqs[c].append(xyz)
ca_arrays=[np.array(v) for v in seqs.values()]
allA=np.array(pts_all); caM=np.array([x for c,x in chains]); mean=caM.mean(0)
allA-=mean; ca_arrays=[a-mean for a in ca_arrays]
letters='BDFHJLNPRTVXZ'; templates={}
for ch in letters:
 im=Image.new('L',(120,120),0); d=ImageDraw.Draw(im); bbox=d.textbbox((0,0),ch,font=font); w=bbox[2]-bbox[0]; h=bbox[3]-bbox[1]
 im2=Image.new('L',(max(1,w),max(1,h)),0); d2=ImageDraw.Draw(im2); d2.text((-bbox[0],-bbox[1]),ch,font=font,fill=255)
 scale=58/max(w,h); nw=max(1,int(round(w*scale))); nh=max(1,int(round(h*scale))); im2=im2.resize((nw,nh),Image.LANCZOS)
 canvas=Image.new('L',(64,64),0); canvas.paste(im2,((64-nw)//2,(64-nh)//2)); templates[ch]=np.array(canvas)>100

def render_points(pts,R,size=64,maxdim=58,dilate=1):
 q=(pts@R.T)[:,:2]; minp=q.min(0); maxp=q.max(0); span=maxp-minp
 if span.max()<1e-9: span=np.array([1.,1.])
 scale=maxdim/span.max(); pad=(size-maxdim)/2; offset=pad+(maxdim-span*scale)/2
 q=(q-minp)*scale+offset
 grid=np.zeros((size,size),bool)
 for x,y in q:
  xi=min(size-1,max(0,int(round(x)))); yi=min(size-1,max(0,int(round(y)))); grid[yi,xi]=True
 if dilate: grid=binary_dilation(grid,iterations=dilate)
 return grid

def variants(t): return [t,t[:,::-1],np.rot90(t),np.rot90(t,2),np.rot90(t,3),np.rot90(t,3)[:,::-1],np.rot90(t,2)[:,::-1],np.rot90(t,1)[:,::-1]]
def best_iou(g,t):
 ga=g.sum(); ta=t.sum(); mi=max(int(fftconvolve(g.astype(float),tv[::-1,::-1].astype(float),mode='full').max()) for tv in variants(t)); union=ga+ta-mi
 return mi/union if union else 0
rots=[np.eye(3),np.linalg.svd(caM-caM.mean(0))[2]]
np.random.seed(2)
for _ in range(300): rots.append(Rotation.random().as_matrix())
for mode in ['ca_points','all_points']:
 print('\\nMODE',mode)
 for dil in [1,2,3,4,5]:
  best={ch:0 for ch in letters}; st=time.time()
  for R in rots:
   if mode=='ca_points': pts=np.vstack(ca_arrays)
   else: pts=allA
   g=render_points(pts,R,dilate=dil)
   for ch in letters:
    s=best_iou(g,templates[ch]); best[ch]=max(best[ch],s)
  print('dil',dil,'time',round(time.time()-st,1),'top',sorted(best.items(),key=lambda kv:-kv[1])[:5])
PY"

